from __future__ import annotations

import json
import os
import queue
import subprocess
import threading
import time
from collections import deque
from pathlib import Path
from typing import Any, Callable, Deque, TypeVar
from uuid import uuid4

from pydantic import BaseModel, ConfigDict

JsonPrimitive = None | bool | int | float | str
JsonValue = JsonPrimitive | list["JsonValue"] | dict[str, "JsonValue"]
JsonObject = dict[str, JsonValue]

T = TypeVar("T", bound=BaseModel)


class TransportClosedError(RuntimeError):
    pass


class JsonRpcError(RuntimeError):
    def __init__(self, code: int, message: str, data: JsonValue | None = None) -> None:
        super().__init__(f"JSON-RPC error {code}: {message}")
        self.code = code
        self.message = message
        self.data = data


class ClientConfig(BaseModel):
    runtime_binary: str | Path | None = None
    bridge_binary: str | Path | None = None
    launch_args: list[str] | None = None
    cwd: str | Path | None = None
    env_overrides: dict[str, str] | None = None
    default_request_timeout: float | None = None
    shutdown_timeout: float = 1.0
    model_config = ConfigDict(arbitrary_types_allowed=True)


class Notification(BaseModel):
    method: str
    params: dict[str, JsonValue]


class IncomingRequest(BaseModel):
    id: JsonValue
    method: str
    params: dict[str, JsonValue]


class SessionPromptResponse(BaseModel):
    messageId: str


class ShutdownResponse(BaseModel):
    pass


class InitializeResponse(BaseModel):
    model_config = ConfigDict(extra="allow")


def _int_or_none(value: Any) -> int | None:
    return value if isinstance(value, int) else None


class NotificationSubscription:
    def __init__(
        self,
        client: "SyncJsonRpcClient",
        subscription_id: str,
        item_queue: "queue.Queue[Notification | BaseException]",
    ) -> None:
        self._client = client
        self.id = subscription_id
        self._queue = item_queue
        self._closed = False

    def __enter__(self) -> "NotificationSubscription":
        return self

    def __exit__(self, exc_type: Any, exc: Any, tb: Any) -> None:
        self.close()

    def close(self) -> None:
        if self._closed:
            return
        self._closed = True
        self._client._unregister_subscription(self.id)

    def get(self, timeout: float | None = None) -> Notification:
        item = self._queue.get(timeout=timeout)
        if isinstance(item, BaseException):
            raise item
        return item

    def drain(self, callback: Callable[[Notification], None]) -> None:
        while True:
            try:
                item = self._queue.get_nowait()
            except queue.Empty:
                return
            if isinstance(item, BaseException):
                raise item
            callback(item)


class SyncJsonRpcClient:
    _BUNDLED_CONFIG_ENV_VAR = "CLAUDE_CODE_CONFIG"

    def __init__(self, config: ClientConfig | None = None) -> None:
        self._config = config or ClientConfig()
        self._state_lock = threading.Lock()
        self._write_lock = threading.Lock()
        self._process: subprocess.Popen[str] | None = None
        self._stdout_thread: threading.Thread | None = None
        self._stderr_thread: threading.Thread | None = None
        self._response_waiters: dict[str, queue.Queue[JsonValue | BaseException]] = {}
        self._notification_queue: queue.Queue[Notification | BaseException] = queue.Queue()
        self._incoming_request_queue: queue.Queue[IncomingRequest | BaseException] = queue.Queue()
        self._subscribers: dict[
            str,
            tuple[
                queue.Queue[Notification | BaseException],
                Callable[[Notification], bool] | None,
            ],
        ] = {}
        self._session_parents: dict[str, str] = {}
        self._stderr_history: Deque[str] = deque(maxlen=200)

    def __enter__(self) -> "SyncJsonRpcClient":
        self.start()
        return self

    def __exit__(self, exc_type: Any, exc: Any, tb: Any) -> None:
        self.close()

    def start(self) -> None:
        with self._state_lock:
            if self._process is not None and self._process.poll() is None:
                return
            self._session_parents.clear()
            env = os.environ.copy()
            if self._config.env_overrides:
                env.update(self._config.env_overrides)
            self._inject_bundled_default_config(env)
            args = self._resolve_launch_args()
            cwd = Path(self._config.cwd).resolve() if self._config.cwd is not None else None
            process = subprocess.Popen(
                args,
                stdin=subprocess.PIPE,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True,
                encoding="utf-8",
                bufsize=1,
                cwd=str(cwd) if cwd is not None else None,
                env=env,
            )
            self._process = process
            self._stdout_thread = threading.Thread(target=self._stdout_reader_loop, name="jsonrpc-stdout-reader", daemon=True)
            self._stderr_thread = threading.Thread(target=self._stderr_reader_loop, name="jsonrpc-stderr-reader", daemon=True)
            self._stdout_thread.start()
            self._stderr_thread.start()

    def close(self) -> None:
        with self._state_lock:
            process = self._process
        if process is None or process.poll() is not None:
            with self._state_lock:
                self._process = None
            return
        try:
            try:
                self.request("shutdown", response_model=ShutdownResponse, timeout=self._config.shutdown_timeout)
            except Exception as exc:
                self._stderr_history.append(f"shutdown request failed: {exc}")
            try:
                if process.stdin is not None and not process.stdin.closed:
                    process.stdin.close()
            except Exception as exc:
                self._stderr_history.append(f"stdin close failed: {exc}")
            if process.poll() is None:
                try:
                    process.terminate()
                except Exception as exc:
                    self._stderr_history.append(f"terminate failed: {exc}")
            try:
                process.wait(timeout=self._config.shutdown_timeout)
            except subprocess.TimeoutExpired:
                try:
                    process.kill()
                finally:
                    try:
                        process.wait(timeout=self._config.shutdown_timeout)
                    except Exception:
                        pass
        finally:
            with self._state_lock:
                self._process = None
            self._fail_all_waiters(self._make_transport_closed_error("transport closed"))
            stdout_thread = self._stdout_thread
            stderr_thread = self._stderr_thread
            current = threading.current_thread()
            if stdout_thread is not None and stdout_thread.is_alive() and stdout_thread is not current:
                stdout_thread.join(timeout=0.2)
            if stderr_thread is not None and stderr_thread.is_alive() and stderr_thread is not current:
                stderr_thread.join(timeout=0.2)

    def initialize(
        self,
        working_directory: str | Path,
        provider_name: str,
        model_name: str,
        max_token_count: int | None = None,
    ) -> InitializeResponse:
        payload: JsonObject = {
            "cwd": str(Path(working_directory).resolve()),
            "provider": provider_name,
            "model": model_name,
        }
        if max_token_count is not None:
            payload["maxTokens"] = max_token_count
        try:
            return self.request("initialize", payload, InitializeResponse)
        except Exception:
            self.close()
            raise

    def session_prompt(
        self,
        session_id: str,
        content: list[JsonObject],
        notification_callback: Callable[[Notification], None] | None = None,
        subscription: NotificationSubscription | None = None,
        timeout: float | None = None,
    ) -> str:
        response = self.request(
            "session/prompt",
            {"sessionId": session_id, "content": content},
            SessionPromptResponse,
            timeout=timeout,
            notification_callback=notification_callback,
            notification_filter=self.make_session_tree_filter(session_id),
            subscription=subscription,
        )
        return response.messageId

    def request(
        self,
        method: str,
        params: JsonObject | None = None,
        response_model: type[T] = ShutdownResponse,
        timeout: float | None = None,
        notification_callback: Callable[[Notification], None] | None = None,
        notification_filter: Callable[[Notification], bool] | None = None,
        subscription: NotificationSubscription | None = None,
    ) -> T:
        result = self.raw_request(
            method=method,
            params=params,
            timeout=timeout,
            notification_callback=notification_callback,
            notification_filter=notification_filter,
            subscription=subscription,
        )
        if not isinstance(result, dict):
            raise TypeError(f"JSON-RPC result for {method!r} must be an object, got {type(result).__name__}")
        return response_model.model_validate(result)

    def raw_request(
        self,
        method: str,
        params: JsonObject | None = None,
        timeout: float | None = None,
        notification_callback: Callable[[Notification], None] | None = None,
        notification_filter: Callable[[Notification], bool] | None = None,
        subscription: NotificationSubscription | None = None,
    ) -> JsonValue:
        request_id = str(uuid4())
        waiter: queue.Queue[JsonValue | BaseException] = queue.Queue(maxsize=1)
        with self._state_lock:
            self._response_waiters[request_id] = waiter
        temporary_subscription: NotificationSubscription | None = None
        active_subscription = subscription
        if notification_callback is not None and active_subscription is None:
            temporary_subscription = self.subscribe(notification_filter)
            active_subscription = temporary_subscription
        message: JsonObject = {"jsonrpc": "2.0", "id": request_id, "method": method}
        if params is not None:
            message["params"] = params
        try:
            self._write_message(message)
        except Exception:
            with self._state_lock:
                self._response_waiters.pop(request_id, None)
            if temporary_subscription is not None:
                temporary_subscription.close()
            raise
        effective_timeout = timeout if timeout is not None else self._config.default_request_timeout
        deadline = None if effective_timeout is None else time.monotonic() + effective_timeout
        try:
            while True:
                if notification_callback is not None and active_subscription is not None:
                    active_subscription.drain(notification_callback)
                wait_timeout: float | None
                if notification_callback is not None and active_subscription is not None:
                    if deadline is None:
                        wait_timeout = 0.05
                    else:
                        remaining = deadline - time.monotonic()
                        if remaining <= 0:
                            diagnostics = self._gather_runtime_diagnostics()
                            message_text = f"request timed out waiting for {method!r}"
                            if diagnostics:
                                message_text = f"{message_text}\n{diagnostics}"
                            raise TimeoutError(message_text)
                        wait_timeout = min(0.05, remaining)
                else:
                    if deadline is None:
                        wait_timeout = None
                    else:
                        remaining = deadline - time.monotonic()
                        if remaining <= 0:
                            diagnostics = self._gather_runtime_diagnostics()
                            message_text = f"request timed out waiting for {method!r}"
                            if diagnostics:
                                message_text = f"{message_text}\n{diagnostics}"
                            raise TimeoutError(message_text)
                        wait_timeout = remaining
                try:
                    item = waiter.get(timeout=wait_timeout)
                except queue.Empty:
                    continue
                if isinstance(item, BaseException):
                    raise item
                return item
        except Exception:
            with self._state_lock:
                self._response_waiters.pop(request_id, None)
            raise
        finally:
            if temporary_subscription is not None:
                temporary_subscription.close()

    def notify(self, method: str, params: JsonObject | None = None) -> None:
        message: JsonObject = {"jsonrpc": "2.0", "method": method}
        if params is not None:
            message["params"] = params
        self._write_message(message)

    def next_notification(self, timeout: float | None = None) -> Notification:
        item = self._notification_queue.get(timeout=timeout)
        if isinstance(item, BaseException):
            raise item
        return item

    def next_incoming_request(self, timeout: float | None = None) -> IncomingRequest:
        item = self._incoming_request_queue.get(timeout=timeout)
        if isinstance(item, BaseException):
            raise item
        return item

    def subscribe(
        self,
        notification_filter: Callable[[Notification], bool] | None = None,
    ) -> NotificationSubscription:
        subscription_id = str(uuid4())
        item_queue: queue.Queue[Notification | BaseException] = queue.Queue()
        with self._state_lock:
            self._subscribers[subscription_id] = (item_queue, notification_filter)
        return NotificationSubscription(self, subscription_id, item_queue)

    def subscribe_session_tree(self, root_session_id: str) -> NotificationSubscription:
        return self.subscribe(self.make_session_tree_filter(root_session_id))

    def respond(self, request_id: JsonValue, result: JsonValue) -> None:
        self._write_message({"jsonrpc": "2.0", "id": request_id, "result": result})

    def respond_error(
        self,
        request_id: JsonValue,
        code: int,
        message: str,
        data: JsonValue | None = None,
    ) -> None:
        error: JsonObject = {"code": code, "message": message}
        if data is not None:
            error["data"] = data
        self._write_message({"jsonrpc": "2.0", "id": request_id, "error": error})

    def make_session_tree_filter(self, root_session_id: str) -> Callable[[Notification], bool]:
        def predicate(notification: Notification) -> bool:
            params = notification.params
            if notification.method in {"subagent.started", "subagent.finished"}:
                parent_id = params.get("parentSessionId")
                child_id = params.get("sessionId")
                if isinstance(parent_id, str) and self._is_descendant_or_self(parent_id, root_session_id):
                    return True
                if isinstance(child_id, str) and child_id == root_session_id:
                    return True
                return False
            session_id = params.get("sessionId")
            return isinstance(session_id, str) and self._is_descendant_or_self(session_id, root_session_id)
        return predicate

    def _unregister_subscription(self, subscription_id: str) -> None:
        with self._state_lock:
            self._subscribers.pop(subscription_id, None)

    def _write_message(self, message: JsonObject) -> None:
        with self._state_lock:
            process = self._process
            stdin = process.stdin if process is not None else None
        if process is None or process.poll() is not None or stdin is None or stdin.closed:
            raise self._make_transport_closed_error("runtime is not running")
        serialized = json.dumps(message, separators=(",", ":")) + "\n"
        with self._write_lock:
            try:
                stdin.write(serialized)
                stdin.flush()
            except Exception as exc:
                diagnostics = self._gather_runtime_diagnostics()
                detail = f"write failed: {exc}"
                if diagnostics:
                    detail = f"{detail}\n{diagnostics}"
                raise TransportClosedError(detail) from exc

    def _stdout_reader_loop(self) -> None:
        try:
            with self._state_lock:
                process = self._process
                stdout = process.stdout if process is not None else None
            if stdout is None:
                self._fail_all_waiters(self._make_transport_closed_error("stdout unavailable"))
                return
            try:
                for line in stdout:
                    text = line.strip()
                    if not text:
                        continue
                    try:
                        message = json.loads(text)
                    except json.JSONDecodeError:
                        continue
                    self._handle_decoded_message(message)
            except Exception as exc:
                self._fail_all_waiters(exc)
        finally:
            self._fail_all_waiters(self._make_transport_closed_error("stdout closed"))

    def _stderr_reader_loop(self) -> None:
        with self._state_lock:
            process = self._process
            stderr = process.stderr if process is not None else None
        if stderr is None:
            return
        for line in stderr:
            text = line.strip()
            if text:
                self._stderr_history.append(text)

    def _handle_decoded_message(self, message: Any) -> None:
        if not isinstance(message, dict):
            return
        raw_id = message.get("id")
        raw_method = message.get("method")
        if raw_id is not None and isinstance(raw_method, str):
            params = message.get("params")
            normalized_params = params if isinstance(params, dict) else {}
            self._incoming_request_queue.put(
                IncomingRequest.model_validate(
                    {"id": raw_id, "method": raw_method, "params": normalized_params}
                )
            )
            return
        if raw_id is not None and "method" not in message:
            request_id = str(raw_id)
            with self._state_lock:
                waiter = self._response_waiters.pop(request_id, None)
            if waiter is None:
                return
            error = message.get("error")
            if isinstance(error, dict):
                code = _int_or_none(error.get("code"))
                err_message = error.get("message")
                if code is None:
                    code = -32000
                if not isinstance(err_message, str):
                    err_message = "Unknown JSON-RPC error"
                waiter.put(JsonRpcError(code, err_message, error.get("data")))
            else:
                waiter.put(message.get("result"))
            return
        if isinstance(raw_method, str) and raw_id is None:
            params = message.get("params")
            normalized_params = params if isinstance(params, dict) else {}
            notification = Notification.model_validate({"method": raw_method, "params": normalized_params})
            self._record_session_parent(notification)
            matched = False
            to_remove: list[str] = []
            with self._state_lock:
                subscribers_snapshot = list(self._subscribers.items())
            for subscription_id, (subscriber_queue, predicate) in subscribers_snapshot:
                try:
                    is_match = True if predicate is None else bool(predicate(notification))
                except Exception:
                    to_remove.append(subscription_id)
                    continue
                if is_match:
                    matched = True
                    subscriber_queue.put(notification)
            for subscription_id in to_remove:
                self._unregister_subscription(subscription_id)
            if not matched:
                self._notification_queue.put(notification)

    def _record_session_parent(self, notification: Notification) -> None:
        if notification.method != "subagent.started":
            return
        parent_id = notification.params.get("parentSessionId")
        child_id = notification.params.get("sessionId")
        if not isinstance(parent_id, str) or not parent_id:
            return
        if not isinstance(child_id, str) or not child_id:
            return
        if parent_id == child_id:
            return
        with self._state_lock:
            self._session_parents[child_id] = parent_id

    def _is_descendant_or_self(self, session_id: str, root_session_id: str) -> bool:
        current = session_id
        seen: set[str] = set()
        while True:
            if current == root_session_id:
                return True
            if current in seen:
                return False
            seen.add(current)
            with self._state_lock:
                parent = self._session_parents.get(current)
            if not parent:
                return False
            current = parent

    def _fail_all_waiters(self, exc: BaseException) -> None:
        with self._state_lock:
            waiters = list(self._response_waiters.values())
            subscribers = [entry[0] for entry in self._subscribers.values()]
            self._response_waiters.clear()
            self._subscribers.clear()
        for waiter in waiters:
            try:
                waiter.put_nowait(exc)
            except queue.Full:
                pass
        for subscriber in subscribers:
            subscriber.put(exc)
        self._notification_queue.put(exc)
        self._incoming_request_queue.put(exc)

    def _make_transport_closed_error(self, reason: str) -> TransportClosedError:
        diagnostics = self._gather_runtime_diagnostics()
        message = reason
        if diagnostics:
            message = f"{reason}\n{diagnostics}"
        return TransportClosedError(message)

    def _gather_runtime_diagnostics(self) -> str:
        parts: list[str] = []
        with self._state_lock:
            process = self._process
            stderr_thread = self._stderr_thread
        if process is not None:
            exit_code = process.poll()
            if exit_code is not None:
                if stderr_thread is not None and stderr_thread.is_alive() and threading.current_thread() is not stderr_thread:
                    stderr_thread.join(timeout=0.1)
                parts.append(f"process exit code: {exit_code}")
        stderr_tail = list(self._stderr_history)
        if stderr_tail:
            parts.append("stderr tail:")
            parts.extend(stderr_tail)
        return "\n".join(parts)

    def _resolve_launch_args(self) -> list[str]:
        if self._config.launch_args is not None:
            return list(self._config.launch_args)
        if self._config.runtime_binary is not None:
            return [str(Path(self._config.runtime_binary))]
        if self._config.bridge_binary is not None:
            return [str(Path(self._config.bridge_binary))]
        try:
            from claude_code_sdk._runtime import get_bundled_launch_args
        except ImportError as exc:
            raise FileNotFoundError(
                "Bundled runtime launcher is unavailable. Install the package extras that include the bundled runtime, or configure an explicit runtime_binary, bridge_binary, or launch_args override."
            ) from exc
        return list(get_bundled_launch_args())

    def _inject_bundled_default_config(self, env: dict[str, str]) -> None:
        if self._config.launch_args is not None:
            return
        if self._config.runtime_binary is not None:
            return
        if self._config.bridge_binary is not None:
            return
        if self._BUNDLED_CONFIG_ENV_VAR in env:
            return
        try:
            from claude_code_sdk._runtime import get_bundled_default_config_path
        except ImportError:
            return
        env[self._BUNDLED_CONFIG_ENV_VAR] = str(get_bundled_default_config_path())


__all__ = [
    "ClientConfig",
    "IncomingRequest",
    "InitializeResponse",
    "JsonObject",
